/* global document, Office, Word */

const API_BASE =
  window.location.hostname === "localhost"
    ? "http://localhost:8787"
    : "https://nh63xr91-8787.uks1.devtunnels.ms"

const AI_AUTHOR = "Fuse Legal AI"
const SEARCH_LIMIT = 200

type Suggestion = {
  kind: "replace" | "insert" | "instruct"
  old?: string | null
  new?: string | null
  after?: string | null
  instruction?: string | null
}

type Finding = {
  criterion: string
  rule_id?: string | null
  scope: "clause" | "document"
  clause_anchor?: string | null
  quote?: string | null
  severity: "P1" | "P2" | "P3"
  problem: string
  impact?: string | null
  verdict?: "CONFIRMED" | "PLAUSIBLE" | "REFUTED" | null
  suggestion?: Suggestion | null
}

type Extraction = {
  field: string
  value: string
  quote: string
}

type ChatResponse = {
  reply: string
  findings: Finding[]
  extractions: Extraction[]
}

const sessionId = crypto.randomUUID()
let inWord = false
let busy = false

Office.onReady((info) => {
  inWord = info.host === Office.HostType.Word
  if (!inWord) {
    document.getElementById("browser-doc")!.style.display = "block"
  }
  document.getElementById("chat-send")!.onclick = () => sendChat()
  document.getElementById("chip-review")!.onclick = () =>
    sendChat("Review this document against the Fuse NDA style guide.", "review")
  document.getElementById("chip-summarize")!.onclick = () => sendChat("Summarize the key terms of this contract.")
  document.getElementById("chat-input")!.onkeydown = (event) => {
    if ((event as KeyboardEvent).key === "Enter") sendChat()
  }
  appendBubble("assistant", "Hi, I'm Fuse's legal agent. Ask me anything about this contract, or start with a review.")
})

function setStatus(text: string) {
  document.getElementById("status")!.textContent = text
}

async function getDocumentText(): Promise<string> {
  if (!inWord) {
    return (document.getElementById("doc-input") as HTMLTextAreaElement).value
  }
  return Word.run(async (context) => {
    const body = context.document.body
    body.load("text")
    await context.sync()
    return body.text
  })
}

async function post<T>(path: string, payload: unknown): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Tunnel-Skip-AntiPhishing-Page": "true" },
    body: JSON.stringify(payload),
  })
  if (!response.ok) {
    const detail = await response.text()
    throw new Error(`${path} failed (${response.status}): ${detail}`)
  }
  return response.json() as Promise<T>
}

async function sendChat(canned?: string, action: "chat" | "review" = "chat") {
  if (busy) {
    return
  }
  const input = document.getElementById("chat-input") as HTMLInputElement
  const message = canned ?? input.value.trim()
  if (!message) {
    return
  }
  if (!canned) {
    input.value = ""
  }
  appendBubble("user", message)
  busy = true
  setStatus(
    action === "review"
      ? "Running the NDA review pipeline (about two minutes)…"
      : "The agent is working…"
  )
  const typing = showTyping()
  try {
    const documentText = await getDocumentText()
    const started = await post<{ job_id: string }>("/chat", {
      session_id: sessionId,
      message,
      document_text: documentText || null,
      action,
    })
    const live: { bubble: HTMLElement | null } = { bubble: null }
    const result = await pollReview(started.job_id, action, (partial) => {
      typing.remove()
      if (live.bubble === null) {
        live.bubble = appendBubble("assistant", "")
      }
      live.bubble.textContent = partial
    })
    live.bubble?.remove()
    if (result.reply) {
      appendBubble("assistant", result.reply)
    }
    if (result.extractions.length > 0) {
      appendCard(renderContractProfile(result.extractions))
    }
    const cards = result.findings.map((finding) => {
      const card = renderFinding(finding)
      appendCard(card)
      return card
    })
    if (inWord && result.findings.length > 0) {
      setStatus("Adding suggested edits to the document…")
      const outcomes = await applyAllFindings(result.findings)
      outcomes.forEach((outcome, index) => markApplied(cards[index], outcome))
    }
    setStatus("Ready.")
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    appendBubble("assistant", `Something went wrong: ${message}. Please try again.`)
    setStatus("Error — see chat.")
  } finally {
    typing.remove()
    busy = false
  }
}

const PHASE_LABELS: Record<string, string> = {
  starting: "starting up",
  thinking: "thinking",
  classify: "classifying the document",
  review: "reviewing against the style guide",
  verify: "verifying and drafting suggestions",
}

async function pollReview(
  jobId: string,
  action: "chat" | "review" = "review",
  onPartial?: (text: string) => void
): Promise<ChatResponse> {
  const interval = action === "chat" ? 1000 : 4000
  let consecutiveFailures = 0
  for (let attempt = 0; attempt < 300; attempt++) {
    await new Promise((resolve) => setTimeout(resolve, interval))
    let state: {
      status: string
      phase?: string | null
      partial?: string
      result?: ChatResponse
      detail?: string
    }
    try {
      const response = await fetch(`${API_BASE}/review/${jobId}`, {
        headers: { "X-Tunnel-Skip-AntiPhishing-Page": "true" },
      })
      if (!response.ok) {
        throw new Error(`review poll failed (${response.status})`)
      }
      state = await response.json()
      consecutiveFailures = 0
    } catch (error) {
      consecutiveFailures += 1
      if (consecutiveFailures >= 8) {
        throw error
      }
      setStatus("Connection hiccup — retrying…")
      continue
    }
    if (state.status === "done" && state.result) {
      return state.result
    }
    if (state.status === "error") {
      throw new Error(state.detail ?? "review failed")
    }
    if (state.partial && onPartial) {
      onPartial(state.partial)
    }
    const label = PHASE_LABELS[state.phase ?? ""] ?? state.phase ?? "working"
    setStatus(action === "review" ? `Review running: ${label}…` : `The agent is ${label}…`)
  }
  throw new Error("the agent timed out")
}

function showTyping(): HTMLElement {
  const bubble = document.createElement("div")
  bubble.className = "typing"
  bubble.innerHTML = "<span></span><span></span><span></span>"
  appendCard(bubble)
  return bubble
}

function findingLabel(finding: Finding): string {
  return finding.rule_id ?? finding.criterion
}

function commentText(finding: Finding): string {
  let text = `[${finding.severity}] ${findingLabel(finding)} — ${finding.problem}`
  if (finding.impact) {
    text += ` Impact: ${finding.impact}`
  }
  if (finding.verdict === "PLAUSIBLE") {
    text += " (unverified — raised as a question)"
  }
  if (finding.suggestion?.kind === "instruct" && finding.suggestion.instruction) {
    text += ` Suggestion: ${finding.suggestion.instruction}`
  }
  return text
}

function hasInlineSuggestion(finding: Finding): boolean {
  const suggestion = finding.suggestion
  return Boolean(
    (suggestion?.kind === "replace" && suggestion.old && suggestion.new) ||
      (suggestion?.kind === "insert" && suggestion.after && suggestion.new)
  )
}

function renderFinding(finding: Finding): HTMLElement {
  const card = document.createElement("div")
  const severityClass = finding.severity.toLowerCase()
  card.className = `card card-finding card-${severityClass}`
  const anchor = finding.clause_anchor ? ` · ${finding.clause_anchor}` : ""
  card.innerHTML = `<p class="card-title"><span class="severity severity-${severityClass}">${finding.severity}</span>${findingLabel(finding)}${anchor}</p>`

  const suggestion = finding.suggestion
  let suggestionSection: HTMLElement | null = null
  if (hasInlineSuggestion(finding) && suggestion) {
    suggestionSection = document.createElement("div")
    suggestionSection.className = "card-section card-section-suggestion"
    const preview =
      suggestion.kind === "replace"
        ? `<p class="card-body"><s>${suggestion.old}</s> → <b>${suggestion.new}</b></p>`
        : `<p class="card-body">Insert: <b>${suggestion.new}</b></p>`
    suggestionSection.innerHTML = `<span class="card-section-label">Suggestion</span>${preview}`
    card.appendChild(suggestionSection)
  } else {
    card.classList.add("card-comment-only")
  }

  const commentSection = document.createElement("div")
  commentSection.className = "card-section card-section-comment"
  let commentBody = `<span class="card-section-label">Comment</span><p class="card-body">${finding.problem}</p>`
  if (finding.impact) {
    commentBody += `<p class="card-body">${finding.impact}</p>`
  }
  if (suggestion?.kind === "instruct" && suggestion.instruction) {
    commentBody += `<p class="card-body"><b>${suggestion.instruction}</b></p>`
  } else if (!suggestionSection && finding.quote) {
    commentBody += `<p class="card-body"><span class="card-quote">"${finding.quote}"</span></p>`
  }
  if (finding.verdict === "PLAUSIBLE") {
    commentBody += `<p class="card-note">Unverified — raised as a question</p>`
  }
  commentSection.innerHTML = commentBody
  card.appendChild(commentSection)

  const anchorText = searchAnchor(finding)
  if (inWord && anchorText) {
    card.appendChild(button("Go to clause", () => selectInDocument(anchorText)))
  }
  if (inWord) {
    if (suggestionSection) {
      const section = suggestionSection
      section.appendChild(button("Accept", () => acceptSuggestion(finding, section)))
      section.appendChild(button("Reject", () => rejectSuggestion(finding, section)))
    }
    commentSection.appendChild(button("Keep", () => keepComment(finding, commentSection)))
    commentSection.appendChild(button("Remove", () => removeComment(finding, commentSection)))
  } else {
    card.appendChild(button("Dismiss", () => dismissFinding(finding, card)))
  }
  return card
}

function searchAnchor(finding: Finding): string | null {
  return finding.suggestion?.old ?? finding.quote ?? finding.suggestion?.after ?? finding.clause_anchor ?? null
}

type DocIndex = { original: string; normalized: string; map: number[] }

const CHAR_EQUIVALENTS: Record<string, string> = {
  "\u2018": "'",
  "\u2019": "'",
  "\u201A": "'",
  "\u201C": '"',
  "\u201D": '"',
  "\u201E": '"',
  "\u2013": "-",
  "\u2014": "-",
}

function normalizeWithMap(text: string): DocIndex {
  let normalized = ""
  const map: number[] = []
  let index = 0
  while (index < text.length) {
    if (/\s/.test(text[index])) {
      const runStart = index
      while (index < text.length && /\s/.test(text[index])) {
        index += 1
      }
      if (normalized.length > 0 && index < text.length) {
        normalized += " "
        map.push(runStart)
      }
      continue
    }
    const lower = text[index].toLowerCase()
    normalized += CHAR_EQUIVALENTS[lower] ?? (lower.length === 1 ? lower : text[index])
    map.push(index)
    index += 1
  }
  return { original: text, normalized, map }
}

function resolveAnchor(doc: DocIndex, anchor: string): string | null {
  const target = normalizeWithMap(anchor).normalized
  if (!target) {
    return null
  }
  const at = doc.normalized.indexOf(target)
  if (at === -1) {
    return null
  }
  return doc.original.slice(doc.map[at], doc.map[at + target.length - 1] + 1)
}

function renderContractProfile(extractions: Extraction[]): HTMLElement {
  const card = document.createElement("div")
  card.className = "card"
  const rows = extractions
    .map((extraction) => `<p class="card-body"><strong>${extraction.field}</strong>: ${extraction.value}</p>`)
    .join("")
  const quote = extractions.map((extraction) => extraction.quote).find((text) => text)
  card.innerHTML = `<p class="card-title">Contract profile</p>${rows}${quote ? `<span class="card-quote">"${quote}"</span>` : ""}`
  if (inWord && quote) {
    card.appendChild(button("Highlight", () => selectInDocument(quote)))
  }
  for (const [label, action] of [
    ["👍 Correct", "accepted"],
    ["👎 Wrong", "dismissed"],
  ] as const) {
    const vote = button(label, () => recordProfileVerdict(card, extractions, action))
    vote.classList.add("vote")
    card.appendChild(vote)
  }
  return card
}

async function recordProfileVerdict(
  card: HTMLElement,
  extractions: Extraction[],
  action: "accepted" | "dismissed"
) {
  let reason: string | null = null
  if (action === "dismissed") {
    reason = window.prompt("What did the AI get wrong here?")
    if (!reason) {
      return
    }
  }
  try {
    await post("/labels", {
      session_id: sessionId,
      criterion: "contract_profile",
      action,
      target: "extraction",
      reason,
      final_text: JSON.stringify(Object.fromEntries(extractions.map((extraction) => [extraction.field, extraction.value]))),
    })
  } catch {
    setStatus("Could not record the rating; it was not saved.")
    return
  }
  card.querySelectorAll("button.vote").forEach((vote) => vote.remove())
  card.style.opacity = "0.6"
  setStatus(action === "accepted" ? "Profile marked correct — recorded." : "Profile marked wrong — recorded.")
}

function button(label: string, onClick: () => void): HTMLButtonElement {
  const el = document.createElement("button")
  el.textContent = label
  el.className = "card-button"
  el.onclick = onClick
  return el
}

async function selectInDocument(text: string) {
  await Word.run(async (context) => {
    const body = context.document.body
    body.load("text")
    await context.sync()
    const anchor = resolveAnchor(normalizeWithMap(body.text), text) ?? text
    const results = body.search(anchor.slice(0, SEARCH_LIMIT), { matchCase: false })
    results.load("items")
    await context.sync()
    if (results.items.length > 0) {
      results.items[0].select()
      await context.sync()
    }
  })
}

type ApplyResult = "redline" | "insert" | "comment" | "user-comment" | "not-found"

type PlannedAction = {
  anchor: string
  kind: "redline" | "insert" | "comment"
  buildOoxml: (rangeText: string) => string
}

function planAction(finding: Finding): PlannedAction | null {
  const suggestion = finding.suggestion
  const comment = commentText(finding)
  if (
    suggestion?.kind === "replace" &&
    suggestion.old &&
    suggestion.new &&
    suggestion.old.length <= SEARCH_LIMIT &&
    finding.verdict !== "PLAUSIBLE"
  ) {
    const { old: oldText, new: newText } = suggestion
    return { anchor: oldText, kind: "redline", buildOoxml: (rangeText) => redlineOoxml(rangeText, newText, comment) }
  }
  if (suggestion?.kind === "insert" && suggestion.after && suggestion.new && finding.verdict !== "PLAUSIBLE") {
    const newText = suggestion.new
    return { anchor: suggestion.after, kind: "insert", buildOoxml: () => insertOnlyOoxml(newText, comment) }
  }
  const anchor = searchAnchor(finding)
  if (anchor) {
    return { anchor, kind: "comment", buildOoxml: (rangeText) => commentOnlyOoxml(rangeText, comment) }
  }
  return null
}

const APPLY_PAUSE_MS = 150

async function applyAllFindings(findings: Finding[]): Promise<ApplyResult[]> {
  const plans = findings.map(planAction)
  const results: ApplyResult[] = findings.map(() => "not-found")
  const total = plans.filter((plan) => plan !== null).length
  try {
    await Word.run(async (context) => {
      const body = context.document.body
      body.load("text")
      await context.sync()
      const doc = normalizeWithMap(body.text)
      const searches = plans.map((plan) => {
        if (!plan) {
          return null
        }
        const anchor = resolveAnchor(doc, plan.anchor) ?? plan.anchor
        return body.search(anchor.slice(0, SEARCH_LIMIT), { matchCase: false })
      })
      searches.forEach((collection) => collection?.load("items,text"))
      await context.sync()
      let applied = 0
      for (let index = 0; index < plans.length; index++) {
        const plan = plans[index]
        const items = searches[index]?.items
        if (!plan || !items || items.length === 0) {
          continue
        }
        applied += 1
        setStatus(`Applying edit ${applied} of ${total}…`)
        items[0].insertOoxml(
          plan.buildOoxml(items[0].text),
          plan.kind === "insert" ? Word.InsertLocation.after : Word.InsertLocation.replace
        )
        try {
          await context.sync()
          results[index] = plan.kind
        } catch {
          // This edit failed; it falls through to the comment pass below.
        }
        await new Promise((resolve) => setTimeout(resolve, APPLY_PAUSE_MS))
      }
    })
  } catch {
    // Unresolved findings fall through to the comment pass below.
  }
  const pending = findings
    .map((finding, index) => ({ finding, index }))
    .filter(({ index }) => results[index] === "not-found")
  if (pending.length === 0) {
    return results
  }
  setStatus("Adding comments…")
  try {
    await Word.run(async (context) => {
      const body = context.document.body
      body.load("text")
      await context.sync()
      const doc = normalizeWithMap(body.text)
      const anchored = pending.map(({ finding }) => {
        const rawAnchor = searchAnchor(finding)
        const anchor = rawAnchor ? (resolveAnchor(doc, rawAnchor) ?? rawAnchor) : null
        return anchor ? body.search(anchor.slice(0, SEARCH_LIMIT), { matchCase: false }) : null
      })
      anchored.forEach((collection) => collection?.load("items,text"))
      await context.sync()
      for (const [pendingIndex, { finding, index }] of pending.entries()) {
        const items = anchored[pendingIndex]?.items
        if (items && items.length > 0) {
          items[0].insertOoxml(commentOnlyOoxml(items[0].text, commentText(finding)), Word.InsertLocation.replace)
          try {
            await context.sync()
            results[index] = "comment"
            continue
          } catch {
            // OOXML insert failed on this range; fall through to a user-attributed comment.
          }
        }
        const range = body.paragraphs.getFirst().getRange()
        range.insertComment(`${AI_AUTHOR} — ${commentText(finding)}`)
        results[index] = "user-comment"
      }
      await context.sync()
    })
  } catch {
    // Leave remaining findings as not-found; their cards show no applied badge.
  }
  return results
}

function ooxmlTimestamp(): string {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "Z")
}

function xmlEscape(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
}

function redlineOoxml(oldText: string, newText: string, comment: string): string {
  const date = ooxmlTimestamp()
  return ooxmlPackage(
    `<w:del w:id="101" w:author="${AI_AUTHOR}" w:date="${date}">
       <w:r><w:delText xml:space="preserve">${xmlEscape(oldText)}</w:delText></w:r>
     </w:del>
     <w:ins w:id="102" w:author="${AI_AUTHOR}" w:date="${date}">
       <w:r><w:t xml:space="preserve">${xmlEscape(newText)}</w:t></w:r>
     </w:ins>`,
    comment
  )
}

function insertOnlyOoxml(newText: string, comment: string): string {
  const date = ooxmlTimestamp()
  return ooxmlPackage(
    `<w:ins w:id="102" w:author="${AI_AUTHOR}" w:date="${date}">
       <w:r><w:t xml:space="preserve">${xmlEscape(" " + newText)}</w:t></w:r>
     </w:ins>`,
    comment
  )
}

function commentOnlyOoxml(anchorText: string, comment: string): string {
  return ooxmlPackage(`<w:r><w:t xml:space="preserve">${xmlEscape(anchorText)}</w:t></w:r>`, comment)
}

function ooxmlPackage(paragraphInner: string, comment: string): string {
  const date = ooxmlTimestamp()
  return `<?xml version="1.0" standalone="yes"?>
<?mso-application progid="Word.Document"?>
<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">
  <pkg:part pkg:name="/_rels/.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">
    <pkg:xmlData>
      <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
        <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
      </Relationships>
    </pkg:xmlData>
  </pkg:part>
  <pkg:part pkg:name="/word/_rels/document.xml.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">
    <pkg:xmlData>
      <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
        <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/>
      </Relationships>
    </pkg:xmlData>
  </pkg:part>
  <pkg:part pkg:name="/word/comments.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml">
    <pkg:xmlData>
      <w:comments xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
        <w:comment w:id="1" w:author="${AI_AUTHOR}" w:initials="AI" w:date="${date}">
          <w:p><w:r><w:t xml:space="preserve">${xmlEscape(comment)}</w:t></w:r></w:p>
        </w:comment>
      </w:comments>
    </pkg:xmlData>
  </pkg:part>
  <pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">
    <pkg:xmlData>
      <w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
        <w:body>
          <w:p>
            <w:commentRangeStart w:id="1"/>
            ${paragraphInner}
            <w:commentRangeEnd w:id="1"/>
            <w:r><w:commentReference w:id="1"/></w:r>
          </w:p>
        </w:body>
      </w:document>
    </pkg:xmlData>
  </pkg:part>
</pkg:package>`
}

function markApplied(card: HTMLElement, applied: ApplyResult) {
  const note = document.createElement("p")
  note.className = "card-note"
  note.textContent =
    applied === "redline"
      ? "Redline suggested in the document, attributed to Fuse Legal AI"
      : applied === "insert"
        ? "Insertion suggested in the document, attributed to Fuse Legal AI"
        : applied === "comment"
          ? "Comment added in the document, attributed to Fuse Legal AI"
          : applied === "user-comment"
            ? "Comment added in the document (prefixed Fuse Legal AI)"
            : "Clause not found in the document"
  card.insertBefore(note, card.children[1] ?? null)
}

function markSectionDone(section: HTMLElement, note: string) {
  section.classList.add("card-section-done")
  const status = document.createElement("p")
  status.className = "card-note"
  status.textContent = note
  section.appendChild(status)
}

async function resolveTrackedChanges(inserted: string, accept: boolean) {
  try {
    await Word.run(async (context) => {
      const results = context.document.body.search(inserted.slice(0, SEARCH_LIMIT), { matchCase: false })
      results.load("items")
      await context.sync()
      if (results.items.length > 0) {
        const changes = results.items[0].getTrackedChanges()
        if (accept) {
          changes.acceptAll()
        } else {
          changes.rejectAll()
        }
        await context.sync()
      }
    })
  } catch {
    setStatus(
      accept
        ? "Could not accept the tracked change here; accept it from Word's review pane."
        : "Could not undo the tracked change here; reject it from Word's review pane."
    )
  }
}

async function acceptSuggestion(finding: Finding, section: HTMLElement) {
  const inserted = finding.suggestion?.new
  if (inserted) {
    await resolveTrackedChanges(inserted, true)
  }
  await recordLabel(finding, "accepted", "suggestion")
  markSectionDone(section, "Suggestion accepted")
  setStatus(`Accepted the suggestion for ${findingLabel(finding)}. Recorded for the eval loop.`)
}

async function rejectSuggestion(finding: Finding, section: HTMLElement) {
  const reason = window.prompt("Reason for rejecting the suggestion (required):")
  if (!reason) {
    return
  }
  const inserted = finding.suggestion?.new
  if (inserted) {
    await resolveTrackedChanges(inserted, false)
  }
  await recordLabel(finding, "dismissed", "suggestion", reason)
  markSectionDone(section, "Suggestion rejected")
  setStatus(`Rejected the suggestion for ${findingLabel(finding)}. The agent sees this next turn.`)
}

async function keepComment(finding: Finding, section: HTMLElement) {
  await recordLabel(finding, "accepted", "comment")
  markSectionDone(section, "Comment kept")
  setStatus(`Kept the comment for ${findingLabel(finding)}. Recorded for the eval loop.`)
}

async function removeComment(finding: Finding, section: HTMLElement) {
  const reason = window.prompt("Reason for removing the comment (required):")
  if (!reason) {
    return
  }
  try {
    await Word.run(async (context) => {
      const comments = context.document.body.getRange().getComments()
      comments.load("items/content")
      await context.sync()
      const match = comments.items.find((comment) => comment.content?.includes(findingLabel(finding)))
      if (match) {
        match.delete()
        await context.sync()
      }
    })
  } catch {
    setStatus("Could not delete the comment here; remove it from Word's review pane.")
  }
  await recordLabel(finding, "dismissed", "comment", reason)
  markSectionDone(section, "Comment removed")
  setStatus(`Removed the comment for ${findingLabel(finding)}. The agent sees this next turn.`)
}

async function dismissFinding(finding: Finding, card: HTMLElement) {
  const reason = window.prompt("Reason for dismissing (required):")
  if (!reason) {
    return
  }
  await recordLabel(finding, "dismissed", "finding", reason)
  card.style.opacity = "0.5"
  setStatus(`Dismissed ${findingLabel(finding)}. The agent sees this next turn.`)
}

async function recordLabel(
  finding: Finding,
  action: "accepted" | "dismissed",
  target: "suggestion" | "comment" | "finding",
  reason?: string
) {
  try {
    await post("/labels", {
      session_id: sessionId,
      criterion: findingLabel(finding),
      action,
      target,
      reason: reason ?? null,
    })
  } catch (error) {
    setStatus(`Label not recorded: ${String(error)}`)
  }
}

function appendBubble(role: "user" | "assistant", text: string): HTMLElement {
  const bubble = document.createElement("div")
  bubble.className = role === "user" ? "bubble bubble-user" : "bubble bubble-assistant"
  bubble.textContent = text
  appendCard(bubble)
  return bubble
}

function appendCard(element: HTMLElement) {
  const log = document.getElementById("chat-log")!
  log.appendChild(element)
  log.scrollTop = log.scrollHeight
}
